class _MaxStr:
    __slots__ = ("s",)

    def __init__(self, s):
        self.s = s

    def __lt__(self, other):
        return self.s > other.s


def plan_migrations(applied: list[str], target: list[str], migrations: list[dict]) -> list[str]:
    registry = {}
    for m in migrations:
        mid = m["id"]
        if mid in registry:
            raise ValueError
        registry[mid] = {
            "deps": m["deps"],
            "reversible": m["reversible"],
        }

    deps_map = {}
    for mid, entry in registry.items():
        seen = set()
        unique = []
        for d in entry["deps"]:
            if d == mid:
                raise ValueError
            if d not in registry:
                raise ValueError
            if d not in seen:
                seen.add(d)
                unique.append(d)
        deps_map[mid] = unique

    indeg = {mid: len(deps_map[mid]) for mid in registry}
    dependents = {mid: [] for mid in registry}
    for mid, deps in deps_map.items():
        for d in deps:
            dependents[d].append(mid)

    queue = [mid for mid in registry if indeg[mid] == 0]
    processed = 0
    while queue:
        u = queue.pop()
        processed += 1
        for v in dependents[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    if processed != len(registry):
        raise ValueError

    applied_set = set()
    for a in applied:
        if a not in registry:
            raise ValueError
        applied_set.add(a)

    target_set = set()
    for t in target:
        if t not in registry:
            raise ValueError
        target_set.add(t)

    closure_applied = set()
    stack = list(applied_set)
    while stack:
        u = stack.pop()
        if u in closure_applied:
            continue
        closure_applied.add(u)
        for d in deps_map[u]:
            if d not in closure_applied:
                stack.append(d)
    if closure_applied != applied_set:
        raise ValueError

    desired = set()
    stack = list(target_set)
    while stack:
        u = stack.pop()
        if u in desired:
            continue
        desired.add(u)
        for d in deps_map[u]:
            if d not in desired:
                stack.append(d)

    required_removals = applied_set - desired
    for mid in required_removals:
        if not registry[mid]["reversible"]:
            raise ValueError

    current_applied = set(applied_set)
    plan = []

    remaining = set(required_removals)
    dep_count = {u: 0 for u in remaining}
    for u in remaining:
        for v in dependents[u]:
            if v in remaining:
                dep_count[u] += 1

    heap = []
    for u in remaining:
        if dep_count[u] == 0:
            heapq.heappush(heap, _MaxStr(u))

    while remaining:
        if not heap:
            raise ValueError
        item = heapq.heappop(heap)
        u = item.s
        if u not in remaining:
            continue
        plan.append("-" + u)
        remaining.remove(u)
        current_applied.remove(u)
        for d in deps_map[u]:
            if d in remaining:
                dep_count[d] -= 1
                if dep_count[d] == 0:
                    heapq.heappush(heap, _MaxStr(d))

    missing = set(desired) - current_applied
    dep_missing_count = {}
    for u in missing:
        cnt = 0
        for d in deps_map[u]:
            if d not in current_applied:
                cnt += 1
        dep_missing_count[u] = cnt

    heap = []
    for u in missing:
        if dep_missing_count[u] == 0:
            heapq.heappush(heap, u)

    while missing:
        if not heap:
            raise ValueError
        u = heapq.heappop(heap)
        if u not in missing:
            continue
        plan.append("+" + u)
        missing.remove(u)
        current_applied.add(u)
        for v in dependents[u]:
            if v in missing:
                dep_missing_count[v] -= 1
                if dep_missing_count[v] == 0:
                    heapq.heappush(heap, v)

    return plan
