class FrameParser:
    def __init__(self, max_size: int):
        if max_size < 0:
            raise ValueError("max_size must be non-negative")
        self._max_size = max_size
        self._buf = bytearray()
        self._pos = 0
        self._poisoned = False
        self._finished = False

    def feed(self, chunk: bytes) -> list[str]:
        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            raise ValueError("parser is finished")

        self._buf.extend(chunk)
        out = []
        buf = self._buf
        pos = self._pos
        max_size = self._max_size

        while True:
            available = len(buf) - pos
            if available < 4:
                break

            n = (
                (buf[pos] << 24)
                | (buf[pos + 1] << 16)
                | (buf[pos + 2] << 8)
                | buf[pos + 3]
            )

            if n > max_size:
                self._poisoned = True
                raise ValueError("frame too large")

            if available < 4 + n:
                break

            start = pos + 4
            end = start + n
            try:
                s = buf[start:end].decode("utf-8")
            except UnicodeDecodeError:
                self._poisoned = True
                raise ValueError("malformed UTF-8") from None

            out.append(s)
            pos = end

        self._pos = pos

        if pos == len(buf):
            buf.clear()
            self._pos = 0
        elif pos > 65536 and pos * 2 > len(buf):
            del buf[:pos]
            self._pos = 0

        return out

    def finish(self) -> None:
        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            return None
        if self._pos != len(self._buf):
            self._poisoned = True
            raise ValueError("partial frame at finish")
        self._finished = True
        return None

