    if not isinstance(token, str):
        raise ValueError
    if token == "0":
        return 0
    if not token:
        raise ValueError
    first = token[0]
    if first < '1' or first > '9':
        raise ValueError
    for c in token[1:]:
        if c < '0' or c > '9':
            raise ValueError
    try:
        return int(token)
    except ValueError:
        return 10 ** 18


