    current = document
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise ValueError
            current = current[token]
        elif isinstance(current, list):
            idx = parse_array_index(token)
            if idx >= len(current):
                raise ValueError
            current = current[idx]
        else:
            raise ValueError
    return current


