        return value
    parent = get_value(document, tokens[:-1])
    last = tokens[-1]
    if isinstance(parent, dict):
        parent[last] = value
    elif isinstance(parent, list):
        if last == '-':
            parent.append(value)
        else:
            idx = parse_array_index(last)
            if idx > len(parent):
                raise ValueError
            parent.insert(idx, value)
    else:
        raise ValueError
    return document


