        if isinstance(x, dict) or isinstance(y, dict):
            if not (isinstance(x, dict) and isinstance(y, dict)):
                return False
            if len(x) != len(y):
                return False
            for k, v in x.items():
                if k not in y:
                    return False
                stack.append((v, y[k]))
            continue
        if x != y:
            return False
    return True


def test_at(document, tokens, expected):
    actual = get_value(document, tokens)
    return json_equal(actual, expected)


def is_proper_descendant(dest_tokens, source_tokens):
    return (
        len(dest_tokens) > len(source_tokens)
        and dest_tokens[:len(source_tokens)] == source_tokens
    )


def apply_patch(document, operations):
    if not isinstance(operations, list):
        raise ValueError
    doc = deep_copy_json(document)
    for op in operations:
        if not isinstance(op, dict):
            raise ValueError
        if 'op' not in op or 'path' not in op:
            raise ValueError
        opname = op['op']
        if opname not in ('add', 'remove', 'replace', 'move', 'copy', 'test'):
            raise ValueError
        tokens = parse_pointer(op['path'])
        if opname == 'add':
            if 'value' not in op:
                raise ValueError
            doc = add_at(doc, tokens, op['value'], copy_value=True)
        elif opname == 'remove':
            doc, _ = remove_at(doc, tokens)
        elif opname == 'replace':
            if 'value' not in op:
                raise ValueError
            doc = replace_at(doc, tokens, op['value'])
        elif opname == 'test':
            if 'value' not in op:
                raise ValueError
            if not test_at(doc, tokens, op['value']):
                raise ValueError
        elif opname == 'move':
            if 'from' not in op:
                raise ValueError
            from_tokens = parse_pointer(op['from'])
            get_value(doc, from_tokens)
            if from_tokens == tokens:
                continue
            if is_proper_descendant(tokens, from_tokens):
                raise ValueError
            doc, removed = remove_at(doc, from_tokens)
            doc = add_at(doc, tokens, removed, copy_value=False)
        elif opname == 'copy':
            if 'from' not in op:
                raise ValueError
            from_tokens = parse_pointer(op['from'])
            source_value = get_value(doc, from_tokens)
            doc = add_at(doc, tokens, source_value, copy_value=True)
    return doc
