import codecs

class SSEParser:
    def __init__(self):
        self._decoder = codecs.getincrementaldecoder("utf-8")(errors="replace")
        self._finished = False
        self._bom_checked = False
        self._line = []
        self._swallow_lf = False
        self._data = []
        self._event = ""
        self._id = ""
        self._retry = None

    def feed(self, chunk: bytes) -> list[dict]:
        if self._finished:
            raise ValueError("feed() called after finish()")
        if not chunk:
            return []
        text = self._decoder.decode(chunk, final=False)
        return self._consume_text(text)

    def finish(self) -> list[dict]:
        if self._finished:
            return []
        self._finished = True

        events = []
        text = self._decoder.decode(b"", final=True)
        if text:
            events.extend(self._consume_text(text))

        if self._line:
            line = "".join(self._line)
            self._line.clear()
            self._process_line(line, events)

        return events

    def _consume_text(self, text: str) -> list[dict]:
        events = []

        for ch in text:
            if not self._bom_checked:
                self._bom_checked = True
                if ch == "\ufeff":
                    continue

            if self._swallow_lf:
                if ch == "\n":
                    self._swallow_lf = False
                    continue
                self._swallow_lf = False

            if ch == "\n":
                self._end_line(events)
            elif ch == "\r":
                self._end_line(events)
                self._swallow_lf = True
            else:
                self._line.append(ch)

        return events

    def _end_line(self, events: list[dict]) -> None:
        line = "".join(self._line)
        self._line.clear()
        self._process_line(line, events)

    def _process_line(self, line: str, events: list[dict]) -> None:
        if line == "":
            if self._data:
                event_name = self._event if self._event != "" else "message"
                events.append({
                    "event": event_name,
                    "data": "\n".join(self._data),
                    "id": self._id,
                    "retry": self._retry,
                })
            self._data.clear()
            self._event = ""
            return

        if line[0] == ":":
            return

        colon = line.find(":")
        if colon == -1:
            field = line
            value = ""
        else:
            field = line[:colon]
            value = line[colon + 1:]
            if value.startswith(" "):
                value = value[1:]

        if field == "data":
            self._data.append(value)
        elif field == "event":
            self._event = value
        elif field == "id":
            if "\x00" not in value:
                self._id = value
        elif field == "retry":
            if value:
                valid = True
                for ch in value:
                    if ch < "0" or ch > "9":
                        valid = False
                        break
                if valid:
                    number = 0
                    for ch in value:
                        number = number * 10 + (ord(ch) - 48)
                    self._retry = number

