        y.left = x
        self._update(x)
        self._update(y)
        return y

    def _insert(self, root, node):
        if root is None:
            return node
        if node.start < root.start:
            root.left = self._insert(root.left, node)
            if root.left.prio < root.prio:
                root = self._rotate_right(root)
        elif node.start > root.start:
            root.right = self._insert(root.right, node)
            if root.right.prio < root.prio:
                root = self._rotate_left(root)
        else:
            if node.end > root.end:
                root.end = node.end
        self._update(root)
        return root

    def insert(self, start, end):
        node = _Node(start, end, self._next_prio())
        self.root = self._insert(self.root, node)

    def _delete(self, root, key):
        if root is None:
            return None
        if key < root.start:
            root.left = self._delete(root.left, key)
        elif key > root.start:
            root.right = self._delete(root.right, key)
        else:
            if root.left is None:
                return root.right
            if root.right is None:
                return root.left
            if root.left.prio < root.right.prio:
                root = self._rotate_right(root)
                root.right = self._delete(root.right, key)
            else:
                root = self._rotate_left(root)
                root.left = self._delete(root.left, key)
        self._update(root)
        return root

    def delete(self, start):
        self.root = self._delete(self.root, start)

    def find_containing(self, pos):
        cur = self.root
        while cur is not None:
            if pos < cur.start:
                cur = cur.left
            elif pos >= cur.end:
                cur = cur.right
            else:
                return cur
        return None

    def predecessor(self, key):
        cur = self.root
        res = None
        while cur is not None:
            if cur.start < key:
                res = cur
                cur = cur.right
            else:
                cur = cur.left
        return res

    def lower_bound(self, key):
        cur = self.root
        res = None
        while cur is not None:
            if cur.start >= key:
                res = cur
                cur = cur.left
            else:
                cur = cur.right
        return res

    def release(self, s, e):
        pred = self.predecessor(s)
        new_s = s
        if pred is not None and pred.end == s:
            new_s = pred.start
            self.delete(pred.start)

        succ = self.lower_bound(e)
        new_e = e
        if succ is not None and succ.start == e:
            new_e = succ.end
            self.delete(succ.start)

        self.insert(new_s, new_e)

    def take_exact(self, start, size):
        node = self.find_containing(start)
        if node is None or start < node.start or start + size > node.end:
            return False
        a = node.start
        b = node.end
        self.delete(a)
        if a < start:
            self.insert(a, start)
        end = start + size
        if end < b:
            self.insert(end, b)
        return True

    def find_start(self, size, align):
        def rec(node):
            if node is None or node.max_len < size:
                return None
            res = rec(node.left)
            if res is not None:
                return res
            if node.end - node.start >= size:
                x = ((node.start + align - 1) // align) * align
                if x + size <= node.end:
                    return x
            return rec(node.right)

        return rec(self.root)

    def intervals(self):
        res = []
        stack = []
        cur = self.root
        while stack or cur is not None:
            while cur is not None:
                stack.append(cur)
                cur = cur.left
            cur = stack.pop()
            res.append([cur.start, cur.end])
            cur = cur.right
        return res


def allocate_intervals(limit: int, operations: list[dict]) -> dict:
    tree = _FreeTree()
    if limit > 0:
        tree.insert(0, limit)

    active = {}
    results = []

    def fits_at_current(start, old_size, new_size):
        if start + new_size > limit:
            return False
        if new_size <= old_size:
            return True
        old_end = start + old_size
        node = tree.lower_bound(old_end)
        return (
            node is not None
            and node.start == old_end
            and node.end >= start + new_size
        )

    for op in operations:
        kind = op.get("op")

        if kind == "alloc":
            oid = op["id"]
            if oid in active:
                results.append(None)
                continue

            size = op["size"]
            align = op["align"]
            start = tree.find_start(size, align)
            if start is None:
                results.append(None)
            else:
                tree.take_exact(start, size)
                active[oid] = (start, size)
                results.append(start)

        elif kind == "resize":
            oid = op["id"]
            if oid not in active:
                results.append(None)
                continue

            old_start, old_size = active[oid]
            size = op["size"]
            align = op["align"]

            if old_start % align == 0 and fits_at_current(old_start, old_size, size):
                del active[oid]
                tree.release(old_start, old_start + old_size)
                tree.take_exact(old_start, size)
                active[oid] = (old_start, size)
                results.append(old_start)
            else:
                del active[oid]
                tree.release(old_start, old_start + old_size)
                new_start = tree.find_start(size, align)
                if new_start is None:
                    tree.take_exact(old_start, old_size)
                    active[oid] = (old_start, old_size)
                    results.append(None)
                else:
                    tree.take_exact(new_start, size)
                    active[oid] = (new_start, size)
                    results.append(new_start)

        elif kind == "free":
            oid = op["id"]
            if oid in active:
                start, size = active.pop(oid)
                tree.release(start, start + size)
                results.append(True)
            else:
                results.append(False)

        else:
            results.append(None)

    allocations = {oid: [start, size] for oid, (start, size) in active.items()}
    return {
        "results": results,
        "allocations": allocations,
        "free": tree.intervals(),
    }

import heapq

class _MaxStr:
    __slots__ = ('s',)
    def __init__(self, s):
        self.s = s
    def __lt__(self, other):
        return self.s > other.s

def plan_migrations(applied: list[str], target: list[str], migrations: list[dict]) -> list[str]:
    registry = {}
    for entry in migrations:
        mid = entry["id"]
        if mid in registry:
            raise ValueError("duplicate id")
        deps = entry["deps"]
        unique_deps = list(dict.fromkeys(deps))
        registry[mid] = {
            "deps": unique_deps,
            "reversible": entry["reversible"],
        }

    for mid, info in registry.items():
        for dep in info["deps"]:
            if dep == mid:
                raise ValueError("self dependency")
            if dep not in registry:
                raise ValueError("unknown dependency")

    dependents = {mid: [] for mid in registry}
    indegree = {mid: len(info["deps"]) for mid, info in registry.items()}
    for mid, info in registry.items():
        for dep in info["deps"]:
            dependents[dep].append(mid)

    queue = [mid for mid in registry if indegree[mid] == 0]
    processed = 0
    idx = 0
    while idx < len(queue):
        mid = queue[idx]
        idx += 1
        processed += 1
        for d in dependents[mid]:
            indegree[d] -= 1
            if indegree[d] == 0:
                queue.append(d)
    if processed != len(registry):
        raise ValueError("cycle")

    applied_set = set()
    for mid in applied:
        if mid not in registry:
            raise ValueError("unknown applied migration")
        applied_set.add(mid)

    target_set = set()
    for mid in target:
        if mid not in registry:
            raise ValueError("unknown target migration")
        target_set.add(mid)

    for mid in applied_set:
        for dep in registry[mid]["deps"]:
            if dep not in applied_set:
                raise ValueError("applied set is not dependency-closed")

    desired = set()
    stack = list(target_set)
    while stack:
        mid = stack.pop()
        if mid in desired:
            continue
        desired.add(mid)
        for dep in registry[mid]["deps"]:
            if dep not in desired:
                stack.append(dep)

    to_remove = applied_set - desired
    for mid in to_remove:
        if not registry[mid]["reversible"]:
            raise ValueError("irreversible removal required")

    plan = []
    current = set(applied_set)

    count = {mid: 0 for mid in to_remove}
    for mid in current:
        for dep in registry[mid]["deps"]:
            if dep in count:
                count[dep] += 1

    heap = []
    for mid in to_remove:
        if count[mid] == 0:
            heapq.heappush(heap, _MaxStr(mid))

    while heap:
        item = heapq.heappop(heap)
        mid = item.s
        plan.append('-' + mid)
        current.remove(mid)
        for dep in registry[mid]["deps"]:
            if dep in count:
                count[dep] -= 1
                if count[dep] == 0:
                    heapq.heappush(heap, _MaxStr(dep))

    missing = desired - current
    count_fwd = {}
    for mid in missing:
        c = 0
        for dep in registry[mid]["deps"]:
            if dep not in current:
                c += 1
        count_fwd[mid] = c

    heap_fwd = []
    for mid in missing:
        if count_fwd[mid] == 0:
            heapq.heappush(heap_fwd, mid)

    while heap_fwd:
        mid = heapq.heappop(heap_fwd)
        plan.append('+' + mid)
        current.add(mid)
        for d in dependents[mid]:
            if d in count_fwd and d not in current:
                count_fwd[d] -= 1
                if count_fwd[d] == 0:
                    heapq.heappush(heap_fwd, d)

    return plan

