import bisect


def allocate_intervals(limit: int, operations: list[dict]) -> dict:
    allocations = {}
    free = []
    if limit > 0:
        free.append([0, limit])
    results = []

    def find_start(size, align):
        for a, b in free:
            if b - a < size:
                continue
            rem = a % align
            if rem:
                x = a + align - rem
            else:
                x = a
            if x + size <= b:
                return x
        return None

    def add_free(start, end):
        if start >= end:
            return
        idx = bisect.bisect_left(free, [start, -1])
        if idx > 0 and free[idx - 1][1] >= start:
            idx -= 1
            if free[idx][0] < start:
                start = free[idx][0]
            if free[idx][1] > end:
                end = free[idx][1]
            free.pop(idx)
        while idx < len(free) and free[idx][0] <= end:
            if free[idx][1] > end:
                end = free[idx][1]
            free.pop(idx)
        free.insert(idx, [start, end])

    def remove_interval(start, end):
        if start >= end:
            return
        idx = bisect.bisect_right(free, [start, float("inf")]) - 1
        a, b = free[idx]
        if start > a and end < b:
            free[idx] = [a, start]
            free.insert(idx + 1, [end, b])
        elif start > a:
            free[idx] = [a, start]
        elif end < b:
            free[idx] = [end, b]
        else:
            free.pop(idx)

    for op in operations:
        typ = op.get("op")

        if typ == "alloc":
            id_ = op["id"]
            size = op["size"]
            align = op["align"]

            if id_ in allocations:
                results.append(None)
                continue

            start = find_start(size, align)
            if start is None:
                results.append(None)
            else:
                remove_interval(start, start + size)
                allocations[id_] = [start, size]
                results.append(start)

        elif typ == "resize":
            id_ = op["id"]
            size = op["size"]
            align = op["align"]

            if id_ not in allocations:
                results.append(None)
                continue

            old_start, old_size = allocations[id_]
            keep = False

            if old_start % align == 0:
                if size <= old_size:
                    keep = True
                else:
                    e = old_start + old_size
                    new_end = old_start + size
                    idx = bisect.bisect_right(free, [e, float("inf")]) - 1
                    if idx >= 0:
                        a, b = free[idx]
                        if a <= e < b and b >= new_end:
                            keep = True

            if keep:
                if size < old_size:
                    add_free(old_start + size, old_start + old_size)
                elif size > old_size:
                    remove_interval(old_start + old_size, old_start + size)
                allocations[id_] = [old_start, size]
                results.append(old_start)
            else:
                add_free(old_start, old_start + old_size)
                new_start = find_start(size, align)

                if new_start is None:
                    remove_interval(old_start, old_start + old_size)
                    results.append(None)
                else:
                    remove_interval(new_start, new_start + size)
                    allocations[id_] = [new_start, size]
                    results.append(new_start)

        elif typ == "free":
            id_ = op["id"]
            if id_ in allocations:
                start, size = allocations.pop(id_)
                add_free(start, start + size)
                results.append(True)
            else:
                results.append(False)

        else:
            results.append(None)

    alloc_out = {k: [v[0], v[1]] for k, v in allocations.items()}
    free_out = [[a, b] for a, b in free]

    return {
        "results": results,
        "allocations": alloc_out,
        "free": free_out,
    }
