    if isinstance(value, dict):
        if token not in value:
            raise ValueError("missing object member")
        return value[token]
    if isinstance(value, list):
        idx = _parse_index(token)
        if idx >= len(value):
            raise ValueError("array index out of range")
        return value[idx]
    raise ValueError("cannot traverse scalar")


def _get(document, tokens):
