        path.append(next_node)
        current = next_node

    return {"cost": target_cost, "path": path}

def _parse_decimal(s: str) -> tuple[int, int]:
    s = s.strip()
    if s.startswith('+'):
        s = s[1:]
    if s.startswith('-'):
        raise ValueError("negative decimal not allowed")
    if '.' in s:
        int_part, frac_part = s.split('.', 1)
        if '.' in frac_part:
            raise ValueError("invalid decimal")
    else:
        int_part, frac_part = s, ''
    if int_part == '':
        int_part = '0'
    for c in int_part:
        if c < '0' or c > '9':
            raise ValueError("invalid decimal")
    for c in frac_part:
        if c < '0' or c > '9':
            raise ValueError("invalid decimal")
    if frac_part:
        den = 10 ** len(frac_part)
        num = int(int_part) * den + int(frac_part)
    else:
        den = 1
        num = int(int_part)
    return num, den


def _round_half_up_frac(n: int, d: int) -> int:
    return (2 * n + d) // (2 * d)


def _format_cents(c: int) -> str:
    return f"{c // 100}.{c % 100:02d}"


def invoice(items: list[dict], tax_rate: str, coupon: str) -> dict:
    n = len(items)
    grosses = [0] * n
    taxable = [False] * n

    for i, item in enumerate(items):
        unit_num, unit_den = _parse_decimal(item["unit"])
        qty = int(item["qty"])
        grosses[i] = _round_half_up_frac(unit_num * qty * 100, unit_den)
        taxable[i] = bool(item["taxable"])

    subtotal = sum(grosses)

    coupon_num, coupon_den = _parse_decimal(coupon)
    coupon_cents = _round_half_up_frac(coupon_num * 100, coupon_den)
    discount_total = coupon_cents if coupon_cents < subtotal else subtotal

    discounts = [0] * n
    if subtotal > 0 and discount_total > 0:
        base_sum = 0
        remainders = []
        for i, gross in enumerate(grosses):
            prod = discount_total * gross
            base = prod // subtotal
            rem = prod - base * subtotal
            discounts[i] = base
            base_sum += base
            if rem > 0:
                remainders.append((rem, i))

        remaining = discount_total - base_sum
        if remaining > 0:
            remainders.sort(key=lambda x: (-x[0], x[1]))
            for j in range(remaining):
                discounts[remainders[j][1]] += 1

    rate_num, rate_den = _parse_decimal(tax_rate)

    lines_out = []
    total_net = 0
    total_tax = 0

    for i in range(n):
        gross = grosses[i]
        disc = discounts[i]
        net = gross - disc

        if taxable[i]:
            tax = _round_half_up_frac(net * rate_num, rate_den)
        else:
            tax = 0

        total_net += net
        total_tax += tax
        line_total = net + tax

        lines_out.append({
            "gross": _format_cents(gross),
            "discount": _format_cents(disc),
            "net": _format_cents(net),
            "tax": _format_cents(tax),
            "total": _format_cents(line_total),
        })

    invoice_total = total_net + total_tax

    return {
        "lines": lines_out,
        "subtotal": _format_cents(subtotal),
        "discount": _format_cents(discount_total),
        "net": _format_cents(total_net),
        "tax": _format_cents(total_tax),
        "total": _format_cents(invoice_total),
    }

