import heapq
import itertools

def shortest_route(edges: list[list], start: str, goal: str) -> dict | None:
    if start == goal:
        return {"cost": 0, "path": [start]}

    out = {}
    rev = {}
    for e in edges:
        s, d, w = e[0], e[1], e[2]
        out.setdefault(s, []).append((d, w))
        rev.setdefault(d, []).append((s, w))

    dist = {goal: (0, 0)}
    counter = itertools.count()
    heap = [(0, 0, next(counter), goal)]

    while heap:
        cost, hops, _, u = heapq.heappop(heap)
        if dist.get(u) != (cost, hops):
            continue
        for v, w in rev.get(u, ()):
            nc = cost + w
            nh = hops + 1
            old = dist.get(v)
            if old is None or (nc, nh) < old:
                dist[v] = (nc, nh)
                heapq.heappush(heap, (nc, nh, next(counter), v))

    if start not in dist:
        return None

    total_cost, total_hops = dist[start]
    path = [start]
    u = start
    remaining_cost, remaining_hops = total_cost, total_hops

    while u != goal:
        best_v = None
        best_w = None
        for v, w in out.get(u, ()):
            dv = dist.get(v)
            if dv is not None and w + dv[0] == remaining_cost and 1 + dv[1] == remaining_hops:
                if best_v is None or v < best_v:
                    best_v = v
                    best_w = w
        if best_v is None:
            return None
        path.append(best_v)
        remaining_cost -= best_w
        remaining_hops -= 1
        u = best_v

    return {"cost": total_cost, "path": path}
