import re


def _make_chunk(current):
    length = len(current)
    has_q = False
    all_q = True

    for typ, _ in current:
        if typ == 1:
            has_q = True
        else:
            all_q = False

    if not has_q:
        s = ''.join(ch for typ, ch in current)
        return (0, s, length)

    if all_q:
        return (2, None, length)

    parts = []
    for typ, ch in current:
        if typ == 1:
            parts.append('.')
        else:
            parts.append(re.escape(ch))
    return (1, re.compile(''.join(parts), re.DOTALL), length)


def _compile_ordinary(seg):
    chunks = []
    current = []
    starts_with_star = False
    first = True
    last_was_star = False
    i = 0
    n = len(seg)

    while i < n:
        c = seg[i]

        if c == '\\':
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            current.append((0, seg[i + 1]))
            if first:
                starts_with_star = False
                first = False
            last_was_star = False
            i += 2

        elif c == '*':
            if not last_was_star:
                if current:
                    chunks.append(_make_chunk(current))
                    current = []
                if first:
                    starts_with_star = True
                    first = False
                last_was_star = True
            i += 1

        elif c == '?':
            current.append((1, None))
            if first:
                starts_with_star = False
                first = False
            last_was_star = False
            i += 1

        else:
            current.append((0, c))
            if first:
                starts_with_star = False
                first = False
            last_was_star = False
            i += 1

    if current:
        chunks.append(_make_chunk(current))

    ends_with_star = last_was_star if n > 0 else False
    return (chunks, starts_with_star, ends_with_star)


def _chunk_match_at(text, start, chunk):
    kind, val, length = chunk
    if start < 0 or start + length > len(text):
        return False

    if kind == 0:
        return text.startswith(val, start)
    if kind == 2:
        return True

    return val.match(text, start) is not None


def _chunk_find(text, pos, chunk):
    kind, val, length = chunk

    if kind == 0:
        return text.find(val, pos)

    if kind == 2:
        if pos + length <= len(text):
            return pos
        return -1

    m = val.search(text, pos)
    return m.start() if m is not None else -1


def _match_segment(chunks, starts_with_star, ends_with_star, text):
    if not chunks:
        return True

    n = len(text)
    num = len(chunks)
    pos = 0
    next_idx = 0

    if not starts_with_star:
        c = chunks[0]
        if not _chunk_match_at(text, 0, c):
            return False
        pos = c[2]
        next_idx = 1

    end_anchored = not ends_with_star
    last_idx = num - 1 if end_anchored else num

    if next_idx > last_idx:
        return pos == n

    idx = next_idx
    while idx < last_idx:
        c = chunks[idx]
        found = _chunk_find(text, pos, c)
        if found < 0:
            return False
        pos = found + c[2]
        idx += 1

    if end_anchored:
        c = chunks[last_idx]
        start = n - c[2]
        if start < pos:
            return False
        if not _chunk_match_at(text, start, c):
            return False

    return True


def path_glob(pattern: str, path: str) -> bool:
    if pattern == "":
        elements = []
    else:
        raw_segments = pattern.split('/')

        for seg in raw_segments:
            if seg == "":
                raise ValueError("empty segment")

        elements = []
        for seg in raw_segments:
            if seg.endswith('\\'):
                raise ValueError("trailing backslash")

            if seg == '**':
                elements.append(None)
            else:
                elements.append(_compile_ordinary(seg))

    if path == "":
        psegs = []
    else:
        psegs = path.split('/')

    n = len(psegs)
    old = 1 << n

    for i in range(len(elements) - 1, -1, -1):
        elem = elements[i]

        if elem is None:
            if old == 0:
                return False
            old = (1 << old.bit_length()) - 1
        else:
            chunks, starts_with_star, ends_with_star = elem
            candidates = old >> 1
            new = 0

            while candidates:
                lsb = candidates & -candidates
                j = lsb.bit_length() - 1

                if _match_segment(chunks, starts_with_star, ends_with_star, psegs[j]):
                    new |= lsb

                candidates ^= lsb

            if new == 0:
                return False

            old = new

    return (old & 1) != 0
