            results.append(None)

        elif typ == "get":
            key = op["key"]
            item = entries.get(key)
            if item is None:
                results.append(None)
            else:
                entries.move_to_end(key)
                results.append(item[0])

        elif typ == "delete":
            key = op["key"]
            if key in entries:
                del entries[key]
                results.append(True)
            else:
                results.append(False)
            maybe_rebuild()

        elif typ == "items":
