            raise ValueError("duplicate job id")
        id_map[jid] = i
        ids[i] = jid

        duration = job["duration"]
        if not isinstance(duration, int) or isinstance(duration, bool) or duration <= 0:
            raise ValueError("duration must be a positive integer")
        durations[i] = duration

        priority = job["priority"]
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise ValueError("priority must be an integer")
        priorities[i] = priority

    unique_deps = [None] * n
    for i, job in enumerate(jobs):
        jid = ids[i]
        seen = set()
        deps_list = []

        for dep in job["deps"]:
            if dep in seen:
                continue
            seen.add(dep)

            if dep == jid:
                raise ValueError("self dependency")
            if dep not in id_map:
                raise ValueError("unknown dependency")

            deps_list.append(dep)

        unique_deps[i] = deps_list

    indeg = [0] * n
    dependents = [[] for _ in range(n)]

    for i, deps_list in enumerate(unique_deps):
        indeg[i] = len(deps_list)
        for dep in deps_list:
            dependents[id_map[dep]].append(i)

    work = indeg[:]
    queue = deque(i for i, value in enumerate(work) if value == 0)
    processed = 0

    while queue:
        current = queue.popleft()
        processed += 1
        for dependent in dependents[current]:
            work[dependent] -= 1
            if work[dependent] == 0:
                queue.append(dependent)

    if processed != n:
        raise ValueError("cycle detected")

    remaining = indeg

    ready = [
        (-priorities[i], ids[i], i)
        for i in range(n)
        if remaining[i] == 0
    ]
    heapq.heapify(ready)

    running = []
    free_workers = []
    next_worker = 0

    actions = []
    current_time = 0
    assigned = 0

    while assigned < n:
        while running and running[0][0] == current_time:
            _, worker, job_index = heapq.heappop(running)
            heapq.heappush(free_workers, worker)

            for dependent in dependents[job_index]:
                remaining[dependent] -= 1
                if remaining[dependent] == 0:
                    heapq.heappush(
                        ready,
                        (-priorities[dependent], ids[dependent], dependent),
                    )

        while ready:
            if free_workers and (
                next_worker >= workers or free_workers[0] < next_worker
            ):
                worker = heapq.heappop(free_workers)
            elif next_worker < workers:
                worker = next_worker
                next_worker += 1
            else:
                break

            _, job_id, job_index = heapq.heappop(ready)
            end_time = current_time + durations[job_index]

            actions.append(
                {
                    "id": job_id,
                    "start": current_time,
                    "end": end_time,
                    "worker": worker,
                }
            )
            assigned += 1

            heapq.heappush(running, (end_time, worker, job_index))

        if assigned == n:
            break

        if running:
            current_time = running[0][0]
        else:
            raise ValueError("unable to schedule jobs")

    return actions

