import re
from typing import List, Tuple, Optional, Dict

# Token kinds
_LITERAL = 0
_QUESTION = 1
_STAR = 2


class _Part:
    __slots__ = (
        "tokens",
        "length",
        "has_question",
        "literal_string",
        "base_mask",
        "literal_masks",
    )

    def __init__(self, tokens: List[Tuple[int, Optional[str]]]) -> None:
        self.tokens = tokens
        self.length = len(tokens)
        self.has_question = False
        self.literal_string: Optional[str] = None
        self.base_mask = 0
        self.literal_masks: Dict[str, int] = {}

        lit_chars: List[str] = []
        for i, (kind, ch) in enumerate(tokens):
            if kind == _QUESTION:
                self.has_question = True
                self.base_mask |= 1 << i
            else:
                # kind == _LITERAL
                lit_chars.append(ch)  # type: ignore[arg-type]
                self.literal_masks[ch] = self.literal_masks.get(ch, 0) | (1 << i)  # type: ignore[index]

        if not self.has_question:
            self.literal_string = "".join(lit_chars)


class _SegmentMatcher:
    __slots__ = ("starts_with_star", "ends_with_star", "parts")

    def __init__(self, tokens: List[Tuple[int, Optional[str]]]) -> None:
        self.starts_with_star = bool(tokens) and tokens[0][0] == _STAR
        self.ends_with_star = bool(tokens) and tokens[-1][0] == _STAR

        parts: List[_Part] = []
        current: List[Tuple[int, Optional[str]]] = []
        for tok in tokens:
            if tok[0] == _STAR:
                if current:
                    parts.append(_Part(current))
                    current = []
            else:
                current.append(tok)
        if current:
            parts.append(_Part(current))
        self.parts = parts

    @staticmethod
    def _match_at(s: str, part: _Part, start: int) -> bool:
        if start < 0 or start + part.length > len(s):
            return False
        for i, (kind, ch) in enumerate(part.tokens):
            if kind == _QUESTION:
                continue
            if s[start + i] != ch:
                return False
        return True

    @staticmethod
    def _find_part(s: str, part: _Part, start: int) -> int:
        if start < 0:
            start = 0
        if start + part.length > len(s):
            return -1

        if not part.has_question:
            # Fast path: plain substring search.
            return s.find(part.literal_string, start)  # type: ignore[arg-type]

        # Shift-And algorithm for a part containing '?'.
        m = part.length
        base_mask = part.base_mask
        literal_masks = part.literal_masks
        d = 0
        last_bit = 1 << (m - 1)
        n = len(s)
        for i in range(start, n):
            c = s[i]
            mask = base_mask | literal_masks.get(c, 0)
            d = ((d << 1) | 1) & mask
            if d & last_bit:
                return i - m + 1
        return -1

    def match(self, s: str) -> bool:
        parts = self.parts
        if not parts:
            # Pattern segment consists only of stars.
            return True

        pos = 0
        start_idx = 0
        end_idx = len(parts)

        if not self.starts_with_star:
            first = parts[0]
            if not self._match_at(s, first, 0):
                return False
            pos = first.length
            start_idx = 1

        if not self.ends_with_star:
            end_idx -= 1

        # If the first and last part are the same part, it has already been
        # matched at the beginning and must not be matched again at the end.
        if start_idx > end_idx:
            # This can only happen when there is exactly one part and both
            # starts_with_star and ends_with_star are false.  In that case the
            # first match above already checked the whole string.
            return True

        for i in range(start_idx, end_idx):
            part = parts[i]
            idx = self._find_part(s, part, pos)
            if idx == -1:
                return False
            pos = idx + part.length

        if not self.ends_with_star:
            last = parts[-1]
            start_last = len(s) - last.length
            if start_last < pos:
                return False
            if not self._match_at(s, last, start_last):
                return False

        return True


def _parse_pattern_segment(seg: str) -> List[Tuple[int, Optional[str]]]:
    tokens: List[Tuple[int, Optional[str]]] = []
    i = 0
    n = len(seg)
    while i < n:
        c = seg[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash in pattern segment")
            tokens.append((_LITERAL, seg[i + 1]))
            i += 2
        elif c == "*":
            tokens.append((_STAR, None))
            i += 1
        elif c == "?":
            tokens.append((_QUESTION, None))
            i += 1
        else:
            tokens.append((_LITERAL, c))
            i += 1
    return tokens


def path_glob(pattern: str, path: str) -> bool:
    if pattern == "":
        return path == ""

    if pattern.startswith("/") or pattern.endswith("/") or "//" in pattern:
        raise ValueError("invalid pattern: empty segment")

    raw_segments = pattern.split("/")
    matchers: List[Optional[_SegmentMatcher]] = []

    for seg in raw_segments:
        if seg == "":
            raise ValueError("invalid pattern: empty segment")

        tokens = _parse_pattern_segment(seg)

        if seg == "**":
            matchers.append(None)  # globstar
        else:
            matchers.append(_SegmentMatcher(tokens))

    if path == "":
        path_segments: List[str] = []
    else:
        path_segments = path.split("/")

    s_count = len(path_segments)
    dp = [False] * (s_count + 1)
    dp[0] = True

    for matcher in matchers:
        if matcher is None:
            # '**' matches zero or more complete path segments.
            new_dp = [False] * (s_count + 1)
            running = False
            for j in range(s_count + 1):
                if dp[j]:
                    running = True
                new_dp[j] = running
            dp = new_dp
        else:
            new_dp = [False] * (s_count + 1)
            for j in range(s_count):
                if dp[j] and matcher.match(path_segments[j]):
                    new_dp[j + 1] = True
            dp = new_dp

    return dp[s_count]
